#!/usr/bin/env dotnet
#:property AllowUnsafeBlocks=true

Console.WriteLine($"IntPtr.Size = {IntPtr.Size} bytes");

// stackalloc Span<nint>
Span<nint> signed = stackalloc nint[4];
for (int i = 0; i < signed.Length; i++)
    signed[i] = i * 10;

Console.WriteLine("Span<nint> via stackalloc:");
foreach (var v in signed)
    Console.WriteLine($"  {v}");

// stackalloc Span<nuint>
Span<nuint> unsigned = stackalloc nuint[4];
for (int i = 0; i < unsigned.Length; i++)
    unsigned[i] = (nuint)(i * 100);

Console.WriteLine("Span<nuint> via stackalloc:");
foreach (var v in unsigned)
    Console.WriteLine($"  {v}");

// Also works with initializer syntax
Span<nint> init = stackalloc nint[] { 42, -1, nint.MaxValue, nint.MinValue };
Console.WriteLine("Span<nint> with collection initializer:");
foreach (var v in init)
    Console.WriteLine($"  {v}");

